#!/usr/bin/env python3
"""Final verification of the network."""

import sys
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

HOSTS = {
    "B1-PC1": {"host": "192.168.122.31", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.1.10"},
    "B1-PC2": {"host": "192.168.122.32", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.1.11"},
    "B2-PC1": {"host": "192.168.122.33", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.2.10"},
    "B2-PC2": {"host": "192.168.122.34", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.2.11"},
    "B3-PC1": {"host": "192.168.122.35", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.3.10"},
    "B3-PC2": {"host": "192.168.122.36", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.3.11"},
    "B4-PC1": {"host": "192.168.122.37", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.2.1.10"},
    "B4-PC2": {"host": "192.168.122.38", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.2.1.11"},
    "B4-PC3": {"host": "192.168.122.39", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.2.2.10"},
    "B4-PC4": {"host": "192.168.122.40", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.2.2.11"},
}

NON_GUEST = ["B1-PC1", "B1-PC2", "B2-PC1", "B2-PC2", "B3-PC1", "B3-PC2", "B4-PC1", "B4-PC2"]
GUEST = ["B4-PC3", "B4-PC4"]

def ping_from(host_name, target_ip, count=3, timeout=5):
    params = {k: v for k, v in HOSTS[host_name].items() if k != "lab_ip"}
    try:
        conn = ConnectHandler(**params)
        cmd = f"ping -c {count} -W {timeout} {target_ip}"
        out = conn.send_command(cmd, read_timeout=30)
        conn.disconnect()
        success = "0% packet loss" in out or "0.0% packet loss" in out
        return host_name, target_ip, success, out
    except Exception as e:
        return host_name, target_ip, False, str(e)

def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else "all"

    if mode == "non-guest":
        # Non-guest to non-guest (should all pass)
        results = []
        with ThreadPoolExecutor(max_workers=10) as pool:
            futures = []
            for src in NON_GUEST:
                for dst in NON_GUEST:
                    if src != dst:
                        dst_ip = HOSTS[dst]["lab_ip"]
                        futures.append(pool.submit(ping_from, src, dst_ip))
            for f in as_completed(futures):
                results.append(f.result())

        passed = sum(1 for r in results if r[2])
        failed = sum(1 for r in results if not r[2])
        print(f"\nNon-guest to non-guest: {passed} passed, {failed} failed out of {len(results)}")
        for r in sorted(results):
            if not r[2]:
                print(f"  FAIL: {r[0]} -> {r[1]}")

    elif mode == "guest":
        # Guest to guest (should pass)
        results = []
        with ThreadPoolExecutor(max_workers=4) as pool:
            futures = []
            for src in GUEST:
                for dst in GUEST:
