def check_host_reachability():
    print("\n=== 3. HOST REACHABILITY ===\n")

    # Non-guest to non-guest
    results = []
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for src in NON_GUEST:
            for dst in NON_GUEST:
                if src != dst:
                    futures.append(pool.submit(ping_from, src, HOSTS[dst]["lab_ip"]))
        for f in as_completed(futures):
            results.append(f.result())

    passed = sum(1 for r in results if r[2])
    failed = [r for r in results if not r[2]]
    print(f"Non-guest to non-guest: {passed}/56 passed")
    for r in sorted(failed):
        print(f"  FAIL: {r[0]} -> {r[1]}")

    # Guest to guest
    results = []
    with ThreadPoolExecutor(max_workers=4) as pool:
        futures = []
        for src in GUEST:
            for dst in GUEST:
                if src != dst:
                    futures.append(pool.submit(ping_from, src, HOSTS[dst]["lab_ip"]))
        for f in as_completed(futures):
            results.append(f.result())

    passed = sum(1 for r in results if r[2])
    print(f"Guest to guest: {passed}/2 passed")

    # Guest isolation
    results = []
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for src in GUEST:
            for dst in NON_GUEST:
                futures.append(pool.submit(ping_from, src, HOSTS[dst]["lab_ip"], count=2, timeout=3))
        for src in NON_GUEST:
            for dst in GUEST:
                futures.append(pool.submit(ping_from, src, HOSTS[dst]["lab_ip"], count=2, timeout=3))
        for f in as_completed(futures):
            results.append(f.result())

    blocked = sum(1 for r in results if not r[2])
    leaked = [r for r in results if r[2]]
    print(f"Guest isolation: {blocked}/32 blocked")
    for r in sorted(leaked):
        print(f"  LEAKED: {r[0]} -> {r[1]}")

    # Internet
    results = []
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for src in list(NON_GUEST) + GUEST:
            for target in ["8.8.8.8", "1.1.1.1"]:
                futures.append(pool.submit(ping_from, src, target))
        for f in as_completed(futures):
            results.append(f.result())

    passed = sum(1 for r in results if r[2])
    failed = [r for r in results if not r[2]]
    print(f"Internet (8.8.8.8 + 1.1.1.1): {passed}/20 passed")
    for r in sorted(failed):
        print(f"  FAIL: {r[0]} -> {r[1]}")

